        gps_clear_att(&session->gpsdata.attitude);
        if (0 == (session->gpsdata.set & DOP_SET)) {
            // FIXME: put gpsdata.dop in newdata.dop
            gps_clear_dop(&session->gpsdata.dop);
        }
        gps_clear_fix(&session->gpsdata.fix);
