            double quiet_time = (MINIMUM_QUIET_TIME * min_cycle);
            double gap;

            gap = TS_SUB_D(&ts_now, &session->lexer.start_time);

            // used to compare gap > min_cycle, but min_cycle is now
            // so variable as to be not helpful.  Some GPS models can
