                         gap, quiet_time);
                session->sor = ts_now;
                session->lexer.start_char = session->lexer.char_counter;
            }
        }
        session->lexer.start_time = ts_now;

session->lexer.start_time = ts_now;
    }

    if (COMMENT_PACKET <= session->lexer.type) {
        session->observed |= PACKET_TYPEMASK(session->lexer.type);
    }

