        TS_SUB(&delta, &ts_now, &session->gpsdata.online);
        GPSD_LOG(LOG_INF, &session->context->errout,
                 "CORE: hunt on %s failed (%s sec since data)\n",
                 session->gpsdata.dev.path,
                 timespec_str(&delta, ts_buf, sizeof(ts_buf)));
        return ERROR_SET;
    }

